// Local, deliberately conservative cues, not an AI assessment of someone's mood.
export function contextEmotion(text,context=[]){const raw=String(text||'');if(raw.length>600||/[`]|https?:\/\//i.test(raw)||/^\s*>/m.test(raw))return null;const t=raw.toLowerCase().replace(/[’']/g,'');const negative=/\b(no|not|never|isnt|wasnt|dont|cant|ugh|wish|pretending|sarcasm|sarcastic|jk|kidding|sad|upset|angry|hate|died|death|funeral|failed|failure|lost|sick|hurt|depressed|unhappy|crying)\b/;if(negative.test(t)||/yeah right|as if|yay.*(?:more homework|another exam|another test)/.test(t))return null;const badContext=context.some(s=>negative.test(String(s).toLowerCase()));const clearWin=/\b(i|we) (won|passed|got (the job|accepted|promoted))\b/.test(t);if((/\b(yay+|woohoo+|hooray|yippee)\b/.test(t)||/\b(i ?m|im|i am|we ?re|we are) (so |really |super )?(happy|excited|thrilled)\b/.test(t)||clearWin)&&(!badContext||clearWin))return 'celebration';if(!badContext&&/\b(love you|love you guys|youre the best|you are the best)\b/.test(t))return 'love';if(!badContext&&/\b(thank you so much|thanks so much|so grateful|really appreciate (you|it))\b/.test(t))return 'gratitude';return null}
let overlay,timer,last=0;const seen=new Set();
export function stop(){clearTimeout(timer);overlay?.remove();overlay=null}
export function receive(items,{ownerId,context=[],chat}={}){if(typeof document==='undefined'||document.visibilityState!=='visible'||!window.DockGroupMeChat?.isVisible()||document.documentElement.dataset.groupmeMotion==='quick'||matchMedia('(prefers-reduced-motion:reduce)').matches)return;let emotion;for(const m of items.slice(-5)){const key=chat+':'+m.id;if(seen.has(key))continue;seen.add(key);if(seen.size>500)seen.delete(seen.values().next().value);if(String(m.user_id||m.sender_id)===String(ownerId)||m.system||m.sender_type==='system'||m.attachments?.some(a=>a.type==='reply')||!Number.isFinite(m.created_at)||Math.abs(Date.now()-m.created_at*1000)>90000)continue;emotion=contextEmotion(m.text,context)||emotion}if(!emotion||Date.now()-last<10000)return;last=Date.now();stop();overlay=document.createElement('div');overlay.className='context-effect context-'+emotion;overlay.setAttribute('aria-hidden','true');overlay.inert=true;const colors=['#f4cc53','#9ed9cb','#b6aff5','#f4a8bd'];for(let i=0;i<(emotion==='celebration'?36:12);i++){const bit=document.createElement('i');const side=i%2;bit.style.cssText=`--side:${side?'100%':'0%'};--dx:${(side?-1:1)*(60+Math.random()*innerWidth*.4)}px;--dy:${-150+Math.random()*300}px;--turn:${Math.random()*720}deg;--delay:${Math.random()*180}ms;--color:${colors[i%4]};top:${35+Math.random()*35}%`;overlay.append(bit)}document.body.append(overlay);timer=setTimeout(stop,1600)}
if(typeof window!=='undefined'){window.DockGroupMeContextReactions={receive,stop};document.addEventListener('visibilitychange',()=>{if(document.visibilityState!=='visible')stop()});window.addEventListener('pagehide',stop)}
